{
  "root": "root",
  "state": {
    "weatherMetrics": [
      {
        "metric": "Humidity",
        "value": "68%"
      },
      {
        "metric": "Wind",
        "value": "9 mph from West"
      },
      {
        "metric": "UV Index",
        "value": "5 (Moderate)"
      },
      {
        "metric": "Sunrise",
        "value": "5:29 AM"
      },
      {
        "metric": "Sunset",
        "value": "8:41 PM"
      }
    ],
    "hourlyForecast": [
      {
        "time": "8 AM",
        "temp": "55°F",
        "condition": "Partly Cloudy",
        "rain_chance": "10% Rain Chance"
      },
      {
        "time": "11 AM",
        "temp": "61°F",
        "condition": "Sun Breaks",
        "rain_chance": "10% Rain Chance"
      },
      {
        "time": "2 PM",
        "temp": "66°F",
        "condition": "Partly Sunny",
        "rain_chance": "15% Rain Chance"
      },
      {
        "time": "5 PM",
        "temp": "64°F",
        "condition": "Breezy",
        "rain_chance": "20% Rain Chance"
      },
      {
        "time": "8 PM",
        "temp": "58°F",
        "condition": "Cloudy",
        "rain_chance": "30% Rain Chance"
      }
    ]
  },
  "elements": {
    "root": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "weather_card",
        "recommendations_title",
        "recommendations_summary",
        "recommendations_stack",
        "actions_title",
        "actions_stack",
        "sources_title",
        "sources_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Seattle Outdoor Planner: Saturday, May 16",
        "variant": "h2"
      },
      "children": []
    },
    "weather_card": {
      "type": "Card",
      "props": {},
      "children": [
        "weather_stack"
      ]
    },
    "weather_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "weather_title",
        "weather_image",
        "current_weather_stack",
        "feels_like_text",
        "weather_metrics_table",
        "hourly_title",
        "hourly_table"
      ]
    },
    "weather_title": {
      "type": "Text",
      "props": {
        "text": "Weather Overview & Forecast",
        "variant": "h2"
      },
      "children": []
    },
    "weather_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000002_01_1_seattle_skyline.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "current_weather_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "weather_icon",
        "temp_text",
        "condition_text"
      ]
    },
    "weather_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000002_01_1_cloud-sun.svg"
      },
      "children": []
    },
    "temp_text": {
      "type": "Text",
      "props": {
        "text": "59°F",
        "variant": "h1"
      },
      "children": []
    },
    "condition_text": {
      "type": "Text",
      "props": {
        "text": "Partly Cloudy",
        "variant": "h3"
      },
      "children": []
    },
    "feels_like_text": {
      "type": "Text",
      "props": {
        "text": "Feels like 57°F.",
        "variant": "body"
      },
      "children": []
    },
    "weather_metrics_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "metric",
            "label": "Metric"
          },
          {
            "key": "value",
            "label": "Value"
          }
        ],
        "statePath": "/weatherMetrics",
        "domain": "weather",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "hourly_title": {
      "type": "Text",
      "props": {
        "text": "Hourly Outlook",
        "variant": "h3"
      },
      "children": []
    },
    "hourly_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "temp",
            "label": "Temp"
          },
          {
            "key": "condition",
            "label": "Condition"
          },
          {
            "key": "rain_chance",
            "label": "Rain Chance"
          }
        ],
        "statePath": "/hourlyForecast",
        "domain": "weather",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "recommendations_title": {
      "type": "Text",
      "props": {
        "text": "Activity Recommendations",
        "variant": "h2"
      },
      "children": []
    },
    "recommendations_summary": {
      "type": "Text",
      "props": {
        "text": "The best window for outdoor activities is late morning to early afternoon, with peak temperatures and the lowest chance of rain. Conditions will become breezier with a higher rain risk later in the day."
      },
      "children": []
    },
    "recommendations_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "walk_card",
        "museum_card",
        "picnic_card"
      ]
    },
    "walk_card": {
      "type": "Card",
      "props": {},
      "children": [
        "walk_stack"
      ]
    },
    "walk_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "padding": 16
      },
      "children": [
        "walk_image",
        "walk_title_stack",
        "walk_text"
      ]
    },
    "walk_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000002_01_3_seattle_park.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "walk_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "walk_icon",
        "walk_title"
      ]
    },
    "walk_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000002_01_2_tree.svg"
      },
      "children": []
    },
    "walk_title": {
      "type": "Text",
      "props": {
        "text": "High Recommendation: Afternoon Walk",
        "variant": "h3"
      },
      "children": []
    },
    "walk_text": {
      "type": "Text",
      "props": {
        "text": "A walk is ideal between 11 AM and 3 PM. You'll catch the day's warmest temperatures and best chance of sun. Consider Discovery Park or the waterfront for scenic views."
      },
      "children": []
    },
    "museum_card": {
      "type": "Card",
      "props": {},
      "children": [
        "museum_stack"
      ]
    },
    "museum_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "padding": 16
      },
      "children": [
        "museum_image",
        "museum_title_stack",
        "museum_text"
      ]
    },
    "museum_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000002_01_5_seattle_museum.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "museum_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "museum_icon",
        "museum_title"
      ]
    },
    "museum_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000002_01_3_building.svg"
      },
      "children": []
    },
    "museum_title": {
      "type": "Text",
      "props": {
        "text": "Safe Alternative: Museum Visit",
        "variant": "h3"
      },
      "children": []
    },
    "museum_text": {
      "type": "Text",
      "props": {
        "text": "A museum visit is an excellent all-weather choice. This is the best option if your plans extend into the evening when rain becomes more likely."
      },
      "children": []
    },
    "picnic_card": {
      "type": "Card",
      "props": {},
      "children": [
        "picnic_stack"
      ]
    },
    "picnic_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "padding": 16
      },
      "children": [
        "picnic_image",
        "picnic_title_stack",
        "picnic_text"
      ]
    },
    "picnic_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000002_01_7_picnic_park.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "picnic_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "picnic_icon",
        "picnic_title"
      ]
    },
    "picnic_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000002_01_8_wind.svg"
      },
      "children": []
    },
    "picnic_title": {
      "type": "Text",
      "props": {
        "text": "Not Recommended: Picnic",
        "variant": "h3"
      },
      "children": []
    },
    "picnic_text": {
      "type": "Text",
      "props": {
        "text": "A picnic is risky. The increasing chance of rain (up to 30% by evening) and breezy conditions, especially after 5 PM, make it an unreliable choice for the day."
      },
      "children": []
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md"
      },
      "children": [
        "parks_button",
        "museums_button"
      ]
    },
    "parks_button": {
      "type": "Button",
      "props": {
        "label": "Find Seattle Parks"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.seattle.gov/parks/allparks"
          }
        }
      }
    },
    "museums_button": {
      "type": "Button",
      "props": {
        "label": "Explore Seattle Museums"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitseattle.org/things-to-do/arts-culture/museums/"
          }
        }
      }
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_button": {
      "type": "Button",
      "props": {
        "label": "Weather Forecast Data",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.weather.gov/"
          }
        }
      }
    }
  }
}
